    @_mutmut_mutated(mutants_xǁProjectAnalyzerǁ_detect_test_framework__mutmut)
    def _detect_test_framework(self, language: str) -> str | None:
        """테스트 프레임워크 감지"""
        if language == "python":
            if (self.workspace / "pytest.ini").exists() or (
                self.workspace / "pyproject.toml"
            ).exists():
                content = (
                    (self.workspace / "pyproject.toml").read_text(errors="ignore")
                    if (self.workspace / "pyproject.toml").exists()
                    else ""
                )
                if "pytest" in content:
                    return "pytest"
            return "pytest"  # 기본값
        elif language in ("javascript", "typescript"):
            pkg_json = self.workspace / "package.json"
            if pkg_json.exists():
                import json

                try:
                    data = json.loads(pkg_json.read_text())
                    deps = {
                        **data.get("dependencies", {}),
                        **data.get("devDependencies", {}),
                    }
                    if "vitest" in deps:
                        return "vitest"
                    elif "jest" in deps:
                        return "jest"
                    elif "mocha" in deps:
                        return "mocha"
                except json.JSONDecodeError:
                    pass
        return None

