    @_mutmut_mutated(mutants_xǁCodeExampleAdapterǁ_apply_fastapi_patterns__mutmut)
    def _apply_fastapi_patterns(self, code: str) -> str:
        """FastAPI 패턴 적용"""
        adapted = code

        # 1. requests → httpx 변환 (모던 비동기 HTTP 클라이언트)
        adapted = re.sub(
            r"\bimport\s+requests\b",
            "import httpx",
            adapted,
        )
        adapted = re.sub(
            r"\bfrom\s+requests\s+import",
            "from httpx import",
            adapted,
        )
        # requests.get/post/put/delete → httpx.AsyncClient().get/post/put/delete
        adapted = re.sub(
            r"\brequests\.get\(",
            "await client.get(",
            adapted,
        )
        adapted = re.sub(
            r"\brequests\.post\(",
            "await client.post(",
            adapted,
        )
        adapted = re.sub(
            r"\brequests\.put\(",
            "await client.put(",
            adapted,
        )
        adapted = re.sub(
            r"\brequests\.delete\(",
            "await client.delete(",
            adapted,
        )
        # response.json() → response.json() (동일)
        # response.text → response.text (동일)

        # 2. Pydantic 모델 사용 패턴
        if "class " in adapted and "BaseModel" not in adapted and "pydantic" not in adapted:
            # 모델 클래스처럼 보이는 것에 BaseModel 상속 제안 (주석으로)
            pass

        # 3. 의존성 주입 패턴
        if "def " in adapted and "Depends" not in adapted:
            # 함수 매개변수에 Depends 추가 제안
            pass

        return adapted

