class CodeExampleApplier:
    """변환된 코드를 파일에 적용"""

    @_mutmut_mutated(mutants_xǁCodeExampleApplierǁ__init____mutmut)
    def __init__(self, workspace: str | Path):
        self.workspace = Path(workspace).resolve()

    def xǁCodeExampleApplierǁ__init____mutmut_orig(self, workspace: str | Path):
        self.workspace = Path(workspace).resolve()

    def xǁCodeExampleApplierǁ__init____mutmut_1(self, workspace: str | Path):
        self.workspace = None

    def xǁCodeExampleApplierǁ__init____mutmut_2(self, workspace: str | Path):
        self.workspace = Path(None).resolve()

    @_mutmut_mutated(mutants_xǁCodeExampleApplierǁapply__mutmut)
    def apply(self, adapted: AdaptedCode, dry_run: bool = False) -> bool:
        """코드 적용"""
        if not adapted.target_file:
            log.warning("타겟 파일이 지정되지 않음")
            return False

        target_path = self.workspace / adapted.target_file
        target_path.parent.mkdir(parents=True, exist_ok=True)

        if dry_run:
            log.info(f"[DRY RUN] {target_path}에 적용 예정")
            return True

        try:
            # 기존 내용 읽기
            existing = ""
            if target_path.exists():
                existing = target_path.read_text(encoding="utf-8")

            # 적용 전략 결정
            if adapted.replace_pattern:
                # 패턴 대체
                new_content = re.sub(
                    adapted.replace_pattern,
                    adapted.adapted,
                    existing,
                    flags=re.MULTILINE | re.DOTALL,
                )
            elif adapted.insert_after:
                # 특정 패턴 뒤에 삽입
                new_content = re.sub(
                    f"({re.escape(adapted.insert_after)})",
                    f"\\1\n\n{adapted.adapted}",
                    existing,
                    flags=re.MULTILINE | re.DOTALL,
                )
            else:
                # 파일 끝에 추가 (기본)
                new_content = existing.rstrip() + f"\n\n{adapted.adapted}\n"

            # 변경사항이 없으면 스킵
            if new_content == existing:
                log.info(f"변경사항 없음: {target_path}")
                return True

            # 백업 후 쓰기
            backup_path = target_path.with_suffix(target_path.suffix + ".bak")
            if target_path.exists():
                target_path.rename(backup_path)

            target_path.write_text(new_content, encoding="utf-8")
            log.info(f"적용 완료: {target_path}")
            return True

        except (OSError, UnicodeError, re.error) as e:
            log.error(f"적용 실패: {target_path} - {e}")
            # 복구
            backup_path = target_path.with_suffix(target_path.suffix + ".bak")
            if backup_path.exists():
                backup_path.rename(target_path)
            return False

